(function applyStaticArabic() {
  if (typeof GLOBAL_RA_LIBRARY === 'undefined' || !Array.isArray(GLOBAL_RA_LIBRARY)) return;
  const norm = (s) => String(s || '').toLowerCase()
    .replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"')
    .replace(/\s+/g, ' ').trim().replace(/[.;:,]+$/, '').trim();
  const dict = new Map(Object.entries(GLOBAL_RA_AR).map(([en, ar]) => [norm(en), ar]));
  const missing = new Set();
  let filled = 0;

  GLOBAL_RA_LIBRARY.forEach((cat) => (cat.items || []).forEach((item) => {
    ['hazard', 'effect', 'ctrl'].forEach((f) => {
      const field = item[f];
      if (!field || !String(field.en || '').trim() || String(field.ar || '').trim()) return;
      const out = String(field.en).split('\n').map((line) => {
        if (!line.trim()) return '';
        const ar = dict.get(norm(line));
        if (ar === undefined) missing.add(line.trim());
        return ar;
      });
      if (out.every((x) => x !== undefined)) { field.ar = out.join('\n'); filled += 1; }
    });
  }));

  window.GLOBAL_RA_AR_MISSING = [...missing];
  if (missing.size) {
    console.warn(`[globalRisksAr] filled ${filled} field(s); ${missing.size} line(s) have no static Arabic:`, [...missing]);
  }
}());
